    "title": "上个月，润米开内部例会，大家聊到一个问题。\\n\\n你看，以前想弄懂一件事，要找书、找课，慢慢学。\\n\\n现在，直接问AI啊。没听懂，让它讲简单点。还不懂，让它举个例子。\\n\\n遇到问题再问，不就行了吗？\\n\\n所以大家问：AI都这么好用了，以后咱是不是不用再花那么多时间学习了？\\n\\n我的答案是：还是要学习。但理由，和过去不太一样。\\n\\n过去，咱们怎么学习？\\n6岁上小学，22岁大学毕业，背过元素周期表，推过勾股定理，读过一本本书。很多知识，学的时候，还没遇上对应的问题。\\n\\n因为你不知道，将来会遇见",
